// Actual current pg adapter; isolated PostgreSQL/WASM wire only.
const run=async(s,p)=>{let r;try{r=!p&&s.includes(';')?(await db.exec(s)).at(-1):await db.query(s,p);}catch(e){console.error('FIXTURE_SQL',e.message,s);throw e;}for(const f of r.fields||[])if(f.dataTypeID===1114)for(const row of r.rows)if(row[f.name] instanceof Date)row[f.name]=row[f.name].toISOString().slice(0,23).replace('T',' ');return {...r,rowCount:r.rows.length||r.affectedRows||0};};
class Pool{async connect(){const c=await connect();return {query:run,release:c.release};}async query(s,p){const c=await this.connect();try{return await c.query(s,p);}finally{c.release();}}on(){}async end(){}}
require(require.resolve('pg',{paths:[root]})).Pool=Pool;
